  public boolean canJump(int[] nums) {
    Boolean[] memo = new Boolean[nums.length];
    return canReach(nums, 0, memo);
  }

  private boolean canReach(int[] nums, int index, Boolean[] memo) {
    if (index >= nums.length - 1) return true;
    if (memo[index] != null) return memo[index];
    int limit = Math.min(nums.length - 1, index + nums[index]);
    for (int next = index + 1; next <= limit; next++) {
      if (canReach(nums, next, memo)) return memo[index] = true;
    }
    memo[index] = false;
    return false;
  }
}

