  public int leastInterval(char[] tasks, int n) {
    int[] count = new int[26];
    int max = 0;
    for (char task : tasks) {
      count[task - 'A']++;
      max = Math.max(max, count[task - 'A']);
    }

    int maxCount = 0;
    for (int value : count) if (value == max) maxCount++;
    int frame = (max - 1) * (n + 1) + maxCount;
    return Math.max(tasks.length, frame);
  }
}

