      int[] current = heap.poll();
      answer.append((char) ('a' + current[0]));
      current[1]--;
      if (previous != null && previous[1] > 0) heap.offer(previous);
      previous = current;
    }
    return answer.length() == s.length() ? answer.toString() : "";
